def fetch_sequence(chrom, start, end):
    query = urllib.parse.urlencode({"genome": "hg38", "chrom": chrom, "start": start, "end": end})
    data = url_json(f"https://api.genome.ucsc.edu/getData/sequence?{query}")
    seq = data.get("dna", "").upper().replace("\n", "")
    if len(seq) != end - start:
        return ""
    return seq


def fetch_sequences(regions):
    seqs = []
    for idx, region in enumerate(regions, start=1):
        seq = fetch_sequence(region["chrom"], region["start"], region["end"])
        n_frac = seq.count("N") / float(len(seq) or 1)
        simple_frac = max(seq.count(b) for b in BASES) / float(len(seq) or 1) if seq else 1.0
        if seq and n_frac <= 0.10 and simple_frac <= 0.82:
            copied = dict(region)
            copied["seq"] = seq
            seqs.append(copied)
        if idx % 250 == 0:
            time.sleep(0.2)
    return seqs


def fetch_candidate_motifs():
    motifs_by_tf = defaultdict(list)
    provenance = []
    for tf in CANDIDATES:
        query = urllib.parse.urlencode(
            {"collection": "CORE", "search": tf, "format": "json", "page_size": 100}
        )
        listing = url_json(f"https://jaspar.elixir.no/api/v1/matrix/?{query}")
        exact = []
        for row in listing.get("results", []):
            detail = url_json(row["url"] + "?format=json")
            if detail.get("name", "").upper() == tf:
                exact.append(detail)
        by_base = {}
        for detail in exact:
            base = detail["base_id"]
            if base not in by_base or int(detail["version"]) > int(by_base[base]["version"]):
                by_base[base] = detail
        for detail in sorted(by_base.values(), key=lambda d: d["matrix_id"]):
            motifs_by_tf[tf].append(make_pwm(detail["pfm"], detail["matrix_id"]))
            provenance.append((tf, detail["matrix_id"], detail.get("name", ""), detail.get("collection", "")))
    return motifs_by_tf, provenance


def make_pwm(pfm, matrix_id, pseudocount=0.8):
    columns = len(pfm["A"])
    pwm = []
    max_score = 0.0
    min_score = 0.0
    for i in range(columns):
        total = sum(float(pfm[b][i]) for b in BASES)
        col = {}
        col_max = None
        col_min = None
        for b in BASES:
            prob = (float(pfm[b][i]) + pseudocount) / (total + 4.0 * pseudocount)
            val = math.log(prob / 0.25, 2)
            col[b] = val
            col_max = val if col_max is None else max(col_max, val)
            col_min = val if col_min is None else min(col_min, val)
        max_score += col_max
        min_score += col_min
        pwm.append(col)
    return {"id": matrix_id, "pwm": pwm, "min": min_score, "max": max_score}


def best_relative_score(seq, motif):
    pwm = motif["pwm"]
    width = len(pwm)
    denom = motif["max"] - motif["min"]
    best = -1.0
    for s in (seq, seq.translate(RC)[::-1]):
        for i in range(0, len(s) - width + 1):
            window = s[i : i + width]
            if any(b not in BASES for b in window):
                continue
            score = sum(pwm[j][b] for j, b in enumerate(window))
            rel = (score - motif["min"]) / denom if denom else 0.0
            if rel > best:
                best = rel
    return best


def fisher_greater(a, b, c, d):
    n = a + b + c + d
    row1 = a + b
    col1 = a + c

    def log_choose(nn, kk):
        if kk < 0 or kk > nn:
            return float("-inf")
        return math.lgamma(nn + 1) - math.lgamma(kk + 1) - math.lgamma(nn - kk + 1)

    def hyper(x):
        return math.exp(log_choose(col1, x) + log_choose(n - col1, row1 - x) - log_choose(n, row1))

    lo = max(0, row1 - (n - col1))
    hi = min(row1, col1)
    return min(1.0, sum(hyper(x) for x in range(a, hi + 1) if x >= lo))


def motif_table(motifs_by_tf, groups, threshold):
    rows = []
    scores_by_group = {}
    for group_name, regions in groups.items():
        scores_by_group[group_name] = {}
        for tf, motifs in motifs_by_tf.items():
            vals = []
            hits = 0
            for region in regions:
                best = max(best_relative_score(region["seq"], motif) for motif in motifs)
                vals.append(best)
                if best >= threshold:
                    hits += 1
            scores_by_group[group_name][tf] = (hits, vals)

    gained_n = len(groups["gained"])
    bg_n = len(groups["background"])
    lost_n = len(groups["lost"])
    for tf in CANDIDATES:
        gained_hits, gained_vals = scores_by_group["gained"][tf]
        bg_hits, bg_vals = scores_by_group["background"][tf]
        lost_hits, lost_vals = scores_by_group["lost"][tf]
        a, b, c, d = gained_hits, gained_n - gained_hits, bg_hits, bg_n - bg_hits
        odds = ((a + 0.5) * (d + 0.5)) / ((b + 0.5) * (c + 0.5))
        p = fisher_greater(a, b, c, d)
        rows.append(
            {
                "tf": tf,
                "gained_hits": gained_hits,
                "gained_n": gained_n,
                "gained_rate": gained_hits / float(gained_n or 1),
                "background_hits": bg_hits,
                "background_n": bg_n,
                "background_rate": bg_hits / float(bg_n or 1),
                "lost_hits": lost_hits,
                "lost_n": lost_n,
                "lost_rate": lost_hits / float(lost_n or 1),
                "odds_ratio": odds,
                "fisher_p": p,
                "mean_gained_score": sum(gained_vals) / float(len(gained_vals) or 1),
                "mean_background_score": sum(bg_vals) / float(len(bg_vals) or 1),
                "mean_lost_score": sum(lost_vals) / float(len(lost_vals) or 1),
            }
        )
    rows.sort(key=lambda x: (x["fisher_p"], -x["odds_ratio"], x["tf"]))
    return rows


